const tabs = {"Run Log": ["run_date", "client_id", "client_name", "meeting_date", "status", "brief_url", "deck_url", "flags"], "Meeting History": ["client_id", "client_name", "meeting_date", "transcript_link", "summary", "action_items", "strategies_discussed"], "Preparer Notes": ["client_name", "meeting_date", "notes", "received_at"], "Payment Schedule": ["client_id", "client_name", "client_email", "quarter", "due_date", "federal", "state", "approved", "reminded", "notes"], "Reclassification Review": ["client_id", "realm_id", "txn_id", "txn_type", "date", "description", "amount", "proposed_account", "proposed_account_id", "confidence", "approved", "applied", "approved_by"], "Reclass Audit Log": ["applied_at", "client_id", "txn_id", "old_account", "new_account", "approved_by"], "Rules": ["rule_id", "client_id", "match_field", "contains", "target_account", "target_account_id", "active"], "Proposed Rules": ["proposed_at", "client_id", "pattern", "occurrences", "status"], "Proposed Strategies": ["proposed_at", "source", "strategy_name", "description", "status"]};
const sheets = Object.entries(tabs).map(([title, headers]) => ({
  properties: { title },
  data: [{ rowData: [{ values: headers.map(h => ({ userEnteredValue: { stringValue: h } })) }] }]
}));
return [{ json: { payload: { properties: { title: 'QMP Operations' }, sheets } } }];
